# 游戏内存修改器（外部读写 + 反调试绕过）

下面是一套完整可编译的外部修改器。核心思路：**用 `ReadProcessMemory`/`WriteProcessMemory` 做外部读写，不挂调试器**（这本身就绕过了绝大多数基于 PEB / `IsDebuggerPresent` 的检测），再对真正基于 `NtQueryInformationProcess` 的检测做补丁。如果你确实要挂调试器调试它，文章后半段给了目标进程内的 hook。

## 完整代码 `cheat.cpp`

```cpp
// cheat.cpp — x64 外部内存修改器
// 编译 (MSVC):  cl /EHsc /std:c++17 /O2 cheat.cpp
// 编译 (MinGW): g++ -m64 -std=c++17 -O2 -o cheat.exe cheat.cpp -lpsapi
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>
#include <string>
#include <iostream>

typedef LONG(NTAPI* NtQueryInformationProcess_t)(HANDLE, ULONG, PVOID, ULONG, PULONG);

// ============ 提权：拿 SeDebugPrivilege ============
bool EnableDebugPrivilege() {
    HANDLE hTok = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &hTok))
        return false;
    TOKEN_PRIVILEGES tp{};
    tp.PrivilegeCount = 1;
    LookupPrivilegeValueW(nullptr, SE_DEBUG_NAME, &tp.Privileges[0].Luid);
    tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
    SetLastError(0);
    BOOL ok = AdjustTokenPrivileges(hTok, FALSE, &tp, sizeof(tp), nullptr, nullptr);
    CloseHandle(hTok);
    return ok && GetLastError() == ERROR_SUCCESS;
}

// ============ 进程读写封装 ============
class Process {
public:
    HANDLE  hProc = nullptr;
    DWORD   pid   = 0;
    bool    is64  = true;

    bool Attach(const wchar_t* exeName) {
        pid = GetPidByName(exeName);
        if (!pid) { wprintf(L"[!] 找不到进程 %s\n", exeName); return false; }
        hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
        if (!hProc) { wprintf(L"[!] OpenProcess 失败, error=%lu\n", GetLastError()); return false; }
        IsWow64Process(hProc, (BOOL*)&isWow64);
        is64 = !isWow64;
        printf("[+] 已附着 pid=%lu (x%d)\n", pid, is64 ? 64 : 32);
        return true;
    }

    template <typename T>
    bool Read(uintptr_t addr, T& out) {
        SIZE_T got = 0;
        return ReadProcessMemory(hProc, (LPCVOID)addr, &out, sizeof(T), &got)
               && got == sizeof(T);
    }
    template <typename T>
    bool Write(uintptr_t addr, const T& val) {
        SIZE_T put = 0;
        return WriteProcessMemory(hProc, (LPVOID)addr, &val, sizeof(T), &put)
               && put == sizeof(T);
    }

    // 指针链解析: [[[moduleBase+offs[0]]+offs[1]]+offs[2]] -> 返回最终值地址
    uintptr_t Resolve(uintptr_t moduleBase, const std::vector<uintptr_t>& offs) {
        uintptr_t addr = moduleBase;
        for (size_t i = 0; i + 1 < offs.size(); ++i) {
            uintptr_t p = 0;
            if (!Read<uintptr_t>(addr + offs[i], p) || p == 0) return 0;
            addr = p;
        }
        return addr + offs.back();
    }

    // 数值扫描：在可写内存里找 int32 == value
    std::vector<uintptr_t> ScanInt32(int32_t value) {
        std::vector<uintptr_t> hits;
        SYSTEM_INFO si; GetSystemInfo(&si);
        uintptr_t addr = (uintptr_t)si.lpMinimumApplicationAddress;
        uintptr_t end  = (uintptr_t)si.lpMaximumApplicationAddress;
        const size_t BUF = 1 << 20;
        std::vector<uint8_t> buf(BUF);
        MEMORY_BASIC_INFORMATION mbi;

        while (addr < end && VirtualQueryEx(hProc, (LPCVOID)addr, &mbi, sizeof(mbi))) {
            bool writable = (mbi.State == MEM_COMMIT) &&
                (mbi.Protect == PAGE_READWRITE ||
                 mbi.Protect == PAGE_EXECUTE_READWRITE ||
                 mbi.Protect == PAGE_WRITECOPY);
            if (writable) {
                uintptr_t rs = (uintptr_t)mbi.BaseAddress;
                uintptr_t re = rs + mbi.RegionSize;
                for (uintptr_t cur = rs; cur < re; cur += BUF) {
                    size_t want = min(BUF, (size_t)(re - cur));
                    SIZE_T got = 0;
                    if (ReadProcessMemory(hProc, (LPCVOID)cur, buf.data(), want, &got)
                        && got >= 4) {
                        for (size_t i = 0; i + 4 <= got; ++i) {
                            int32_t v; memcpy(&v, buf.data() + i, 4);
                            if (v == value) hits.push_back(cur + i);
                        }
                    }
                }
            }
            uintptr_t next = (uintptr_t)mbi.BaseAddress + mbi.RegionSize;
            if (next <= addr) break;
            addr = next;
        }
        return hits;
    }

    // ============ 反调试绕过：直接改目标进程 PEB ============
    // 关键点：只有当“你”以调试器身份附着时 PEB 才会被置位。
    // 外部 RPM/WPM 本身不触发。此函数用于目标进程里残留的调试标记 / 你自己挂调试器的场景。
    bool PatchRemotePEB() {
        auto NtQIP = (NtQueryInformationProcess_t)
            GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "NtQueryInformationProcess");
        if (!NtQIP) return false;

        struct PBI {
            NTSTATUS ExitStatus;
            PVOID    PebBaseAddress;
            ULONG_PTR AffinityMask;
            ULONG_PTR BasePriority;
            ULONG_PTR UniqueProcessId;
            ULONG_PTR InheritedFromUniqueProcessId;
        } pbi{};

        if (NtQIP(hProc, 0 /*ProcessBasicInformation*/, &pbi, sizeof(pbi), nullptr) != 0)
            return false;

        uintptr_t peb = (uintptr_t)pbi.PebBaseAddress;
        if (!peb) return false;

        bool ok = true;
        BYTE zero1 = 0;
        // PEB->BeingDebugged  (x64: +0x02, x86: +0x02)
        ok &= WriteProcessMemory(hProc, (LPVOID)(peb + 0x02), &zero1, 1, nullptr);

        DWORD zero4 = 0;
        // PEB->NtGlobalFlag  (x64: +0xBC, x86: +0x68)
        ok &= WriteProcessMemory(hProc, (LPVOID)(peb + (is64 ? 0xBC : 0x68)),
                                 &zero4, 4, nullptr);

        // Heap->Flags / ForceFlags  (x64: +0x70/+0x74, x86: +0x40/+0x44)
        uintptr_t heap = 0;
        ReadProcessMemory(hProc, (LPVOID)(peb + (is64 ? 0x30 : 0x18)),
                          &heap, sizeof(heap), nullptr);
        if (heap) {
            WriteProcessMemory(hProc, (LPVOID)(heap + (is64 ? 0x70 : 0x40)), &zero4, 4, nullptr);
            WriteProcessMemory(hProc, (LPVOID)(heap + (is64 ? 0x74 : 0x44)), &zero4, 4, nullptr);
        }
        printf("[+] PEB 反调试标记已清零 (BeingDebugged/NtGlobalFlag/HeapFlags)\n");
        return ok;
    }

private:
    BOOL isWow64 = FALSE;

    static DWORD GetPidByName(const wchar_t* name) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return 0;
        PROCESSENTRY32W pe{ sizeof(pe) };
        DWORD pid = 0;
        if (Process32FirstW(snap, &pe)) {
            do {
                if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
            } while (Process32NextW(snap, &pe));
        }
        CloseHandle(snap);
        return pid;
    }
};

// ============ 取模块基址 ============
uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

// =======================================================================
//                      主流程
// =======================================================================
int wmain(int argc, wchar_t** argv) {
    const wchar_t* target = (argc > 1) ? argv[1] : L"Game.exe";

    EnableDebugPrivilege();

    Process proc;
    if (!proc.Attach(target)) return 1;

    // ① 先清一遍反调试点
    proc.PatchRemotePEB();

    uintptr_t base = GetModuleBase(proc.pid, target);
    printf("[+] %ls 基址 = 0x%llX\n", target, (unsigned long long)base);
