## 3. C 独立版注册机（不依赖 OpenSSL，内置 SHA1）

```c
/* keygen.c  —  gcc -O2 -o keygen keygen.c  ;  ./keygen 3A7FC21B9E0455D8 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

/* ---------------- SHA1 ---------------- */
typedef struct { uint32_t h[5]; uint64_t len; uint8_t b[64]; size_t n; } sha1_t;
static uint32_t R(uint32_t x, int n){ return (x << n) | (x >> (32 - n)); }
static void blk(sha1_t *c, const uint8_t *p){
    uint32_t w[80], a, b, d, e, f, k, t, i;
    for (i = 0; i < 16; i++)
        w[i] = (p[i*4]<<24)|(p[i*4+1]<<16)|(p[i*4+2]<<8)|p[i*4+3];
    for (i = 16; i < 80; i++)
        w[i] = R(w[i-3]^w[i-8]^w[i-14]^w[i-16], 1);
    a=c->h[0]; b=c->h[1]; d=c->h[2]; e=c->h[3]; f=c->h[4];
    for (i = 0; i < 80; i++){
        if (i < 20){ t = (b & d) | ((~b) & e);        k = 0x5A827999; }
        else if (i < 40){ t = b ^ d ^ e;              k = 0x6ED9EBA1; }
        else if (i < 60){ t = (b & d) | (b & e) | (d & e); k = 0x8F1BBCDC; }
        else { t = b ^ d ^ e;                         k = 0xCA62C1D6; }
        uint32_t tt = R(a,5) + t + f + k + w[i];
        f = e; e = d; d = R(b,30); b = a; a = tt;
    }
    c->h[0]+=a; c->h[1]+=b; c->h[2]+=d; c->h[3]+=e; c->h[4]+=f;
}
static void s_init(sha1_t *c){
    c->h[0]=0x67452301; c->h[1]=0xEFCDAB89; c->h[2]=0x98BADCFE;
    c->h[3]=0x10325476; c->h[4]=0xC3D2E1F0; c->len=0; c->n=0;
}
static void s_upd(sha1_t *c, const uint8_t *p, size_t l){
    c->len += (uint64_t)l * 8;
    while (l--){
        c->b[c->n++] = *p++;
        if (c->n == 64){ blk(c, c->b); c->n = 0; }
    }
}
static void s_fin(sha1_t *c, uint8_t out[20]){
    uint64_t L = c->len; uint8_t pad = 0x80, z = 0x00; size_t i;
    s_upd(c, &pad, 1);
    while (c->n != 56) s_upd(c, &z, 1);
    for (i = 0; i < 8; i++) c->b[c->n++] = (uint8_t)(L >> (56 - i*8));
    blk(c, c->b);
    for (i = 0; i < 5; i++){
        out[i*4]   = c->h[i] >> 24;
        out[i*4+1] = c->h[i] >> 16;
        out[i*4+2] = c->h[i] >> 8;
        out[i*4+3] = c->h[i];
    }
}

/* ---------------- 魔改表 ---------------- */
static const char   *ALPHA = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
static const uint8_t MASK[8] = {0x5A,0xA5,0x3C,0xC3,0x69,0x96,0x7E,0xE7};
static const uint8_t BIAS[8] = {0x2B,0x77,0x1D,0xE3,0x54,0x9E,0x31,0xC8};

int main(int argc, char **argv){
