    uint64_t m = strtoull(mid, NULL, 16);
    int v[25];
    for (int i = 0; i < 24; i++){
        uint32_t r = h[i%20] ^ MASK[i%8] ^ (uint8_t)((m >> (i%16)) & 0xFF);
        r = (r + BIAS[i%8] + i*17) & 0xFF;
        r ^= (r >> 4);
        v[i] = r & 0x1F;
    }
    uint32_t s = 0;
    for (int i = 0; i < 24; i++) s = (s*33 + v[i] + i) & 0xFFFFFFFFu;
    v[24] = (s ^ (s>>13) ^ (s>>23)) & 0x1F;

    for (int i = 0; i < 25; i++){
        putchar(ALPHA[v[i]]);
        if ((i % 5) == 4 && i != 24) putchar('-');
    }
    putchar('\n');
    return 0;
