def crtsh(domain):
    names = set()
    try:
        r = requests.get(f"https://crt.sh/?q=%25.{domain}&output=json",
                         timeout=25, headers={"User-Agent": UA})
        for e in r.json():
            for n in str(e.get("name_value", "")).split("\n"):
                n = n.strip().lstrip("*.").lower()
                if n.endswith(domain) and " " not in n:
