def http_get(url, host_header=None, timeout=TIMEOUT):
    headers = {"User-Agent": UA}
    if host_header:
        headers["Host"] = host_header
    return requests.get(url, headers=headers, timeout=timeout,
                        verify=False, allow_redirects=True)


def _fmt(url_ip, port):
    host = f"[{url_ip}]" if ":" in url_ip else url_ip
    return f"{host}:{port}"


def favicon_hash(base, host_header=None):
    try:
        r = http_get(base + "/favicon.ico", host_header)
        if r.status_code == 200 and r.content:
            data = r.content
            if HAVE_MMH3:
                return {"fofa": mmh3.hash(base64.encodebytes(data)),
                        "shodan": mmh3.hash(data)}
            return {"sha": hashlib.sha256(data).hexdigest()[:16]}
    except Exception:
        pass
    return {}


def fingerprint(url, host_header=None):
    fp = {"url": url, "ok": False, "favicon": {}}
    try:
        r = http_get(url, host_header)
    except Exception as e:
        fp["error"] = str(e)
        return fp
    body = r.text or ""
    m = re.search(r"<title[^>]*>(.*?)</title>", body, re.S | re.I)
    title = re.sub(r"\s+", " ", m.group(1)).strip()[:120] if m else ""
    fp.update({
        "ok": True,
        "status": r.status_code,
        "server": r.headers.get("Server", ""),
        "title": title,
        "len": len(body),
        "sha": hashlib.sha256(body.encode("utf-8", "ignore")).hexdigest()[:16],
    })
    base = re.match(r"^(https?://[^/]+)", url)
    if base:
        fp["favicon"] = favicon_hash(base.group(1), host_header)
    return fp


def similarity(base, cand):
    if not cand.get("ok"):
        return 0, ["no-response"]
    score, reasons = 0, []
    if base.get("title") and base["title"] == cand.get("title"):
        score += 40; reasons.append("title")
    bf, cf = base.get("favicon") or {}, cand.get("favicon") or {}
    for k in ("fofa", "shodan", "sha"):
        if bf.get(k) and cf.get(k) and bf[k] == cf[k]:
            score += 40; reasons.append(f"favicon:{k}")
            break
    if base.get("server") and base.get("server") == cand.get("server"):
        score += 10; reasons.append("server")
    if base.get("sha") and base.get("sha") == cand.get("sha"):
        score += 10; reasons.append("body-hash")
    return score, reasons


