    IsWow64Process(hProc, &b);
    return b != FALSE;
}

// ---------- kernel32 在同一 boot session 内基址一致 ----------
// 所以本地 GetProcAddress 得到的地址可以直接传给远端线程
static FARPROC RemoteProc(const char* dll, const char* func) {
    HMODULE h = GetModuleHandleA(dll);
    if (!h) h = LoadLibraryA(dll);
    return h ? GetProcAddress(h, func) : nullptr;
}

// ---------- 远程模块基址查询（手动映射用） ----------
static HMODULE RemoteGetModuleHandle(DWORD pid, const char* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return nullptr;
    MODULEENTRY32 me{};
    me.dwSize = sizeof(me);
    HMODULE ret = nullptr;
    if (Module32First(snap, &me)) {
        do {
            if (_stricmp(me.szModule, modName) == 0) {
                ret = (HMODULE)me.modBaseAddr;
                break;
            }
        } while (Module32Next(snap, &me));
    }
    CloseHandle(snap);
    return ret;
}

// ---------- 从远端 PE 导出表取函数地址 ----------
static FARPROC RemoteGetProcAddress(HANDLE hProc, HMODULE hMod, const char* name) {
    BYTE hdr[0x1000] = {0};
    SIZE_T rd = 0;
    if (!ReadProcessMemory(hProc, hMod, hdr, sizeof(hdr), &rd)) return nullptr;

    auto dos = (PIMAGE_DOS_HEADER)hdr;
    if (dos->e_magic != IMAGE_DOS_SIGNATURE) return nullptr;
    auto nt = (PIMAGE_NT_HEADERS)(hdr + dos->e_lfanew);
    if (nt->Signature != IMAGE_NT_SIGNATURE) return nullptr;

    DWORD expRva = nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress;
    if (!expRva) return nullptr;

    IMAGE_EXPORT_DIRECTORY exp{};
    if (!ReadProcessMemory(hProc, (BYTE*)hMod + expRva, &exp, sizeof(exp), &rd))
        return nullptr;

    std::vector<DWORD> names(exp.NumberOfNames);
    std::vector<WORD>  ords(exp.NumberOfNames);
    std::vector<DWORD> funcs(exp.NumberOfFunctions);
    if (exp.NumberOfNames) {
        ReadProcessMemory(hProc, (BYTE*)hMod + exp.AddressOfNames, names.data(), names.size()*4, &rd);
        ReadProcessMemory(hProc, (BYTE*)hMod + exp.AddressOfNameOrdinals, ords.data(), ords.size()*2, &rd);
    }
    if (exp.NumberOfFunctions)
        ReadProcessMemory(hProc, (BYTE*)hMod + exp.AddressOfFunctions, funcs.data(), funcs.size()*4, &rd);

    for (DWORD i = 0; i < exp.NumberOfNames; ++i) {
        char fname[256] = {0};
        if (!ReadProcessMemory(hProc, (BYTE*)hMod + names[i], fname, sizeof(fname)-1, &rd))
            continue;
        if (strcmp(fname, name) == 0)
            return (FARPROC)((BYTE*)hMod + funcs[ords[i]]);
    }
    return nullptr;
}

static FARPROC RemoteGetProcAddressOrdinal(HANDLE hProc, HMODULE hMod, WORD ordinal) {
    BYTE hdr[0x1000] = {0};
    SIZE_T rd = 0;
    if (!ReadProcessMemory(hProc, hMod, hdr, sizeof(hdr), &rd)) return nullptr;
    auto dos = (PIMAGE_DOS_HEADER)hdr;
    auto nt  = (PIMAGE_NT_HEADERS)(hdr + dos->e_lfanew);
    DWORD expRva = nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress;
    if (!expRva) return nullptr;
    IMAGE_EXPORT_DIRECTORY exp{};
    if (!ReadProcessMemory(hProc, (BYTE*)hMod + expRva, &exp, sizeof(exp), &rd)) return nullptr;
    if (ordinal < exp.Base || ordinal >= exp.Base + exp.NumberOfFunctions) return nullptr;
    DWORD rva = 0;
    ReadProcessMemory(hProc, (BYTE*)hMod + exp.AddressOfFunctions + (ordinal - exp.Base)*4, &rva, 4, &rd);
    return (FARPROC)((BYTE*)hMod + rva);
}

static std::vector<BYTE> ReadFileBytes(const std::wstring& path) {
    HANDLE h = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ,
                           nullptr, OPEN_EXISTING, 0, nullptr);
    if (h == INVALID_HANDLE_VALUE) return {};
    DWORD size = GetFileSize(h, nullptr);
    std::vector<BYTE> buf(size);
    DWORD rd = 0;
    BOOL ok = ReadFile(h, buf.data(), size, &rd, nullptr);
    CloseHandle(h);
    if (!ok) return {};
    buf.resize(rd);
    return buf;
}
