### 3.2 物理内存读取（核心：无句柄访问）

```c
// 通过 CR3 + 物理地址直接读目标进程内存
// 无需 OpenProcess / NtReadVirtualMemory

typedef struct _COPY_MEMORY_BUFFER {
    ULONG64 TargetPid;
    ULONG64 TargetAddress;
    ULONG64 Size;
    PVOID   OutputBuffer;
} COPY_MEMORY_BUFFER, *PCOPY_MEMORY_BUFFER;

NTSTATUS ReadProcessMemoryKernel(ULONG64 Pid, ULONG64 Address, PVOID Buffer, SIZE_T Size)
{
    PEPROCESS TargetProcess = NULL;
    NTSTATUS status = PsLookupProcessByProcessId((HANDLE)Pid, &TargetProcess);
    if (!NT_SUCCESS(status)) return status;

    SIZE_T BytesCopied = 0;
    // MmCopyMemory 不触发 ObCallback，且不开句柄
    MM_COPY_ADDRESS SourceAddress;
    SourceAddress.VirtualAddress = (PVOID)Address;

    // 附加到目标进程地址空间
    KAPC_STATE ApcState;
    KeStackAttachProcess(TargetProcess, &ApcState);

    __try {
        RtlCopyMemory(Buffer, (PVOID)Address, Size);
        status = STATUS_SUCCESS;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        status = GetExceptionCode();
    }

    KeUnstackDetachProcess(&ApcState);
    ObDereferenceObject(TargetProcess);
    return status;
}
```

**更隐蔽方案：CR3 直接遍历（完全不调用 KeStackAttachProcess）**

```c
ULONG64 TranslateVirtualToPhysical(ULONG64 DirectoryTableBase, ULONG64 VirtualAddress)
{
    ULONG64 PageOffset = VirtualAddress & 0xFFF;
    ULONG64 PTE  = (VirtualAddress >> 12) & 0x1FF;
    ULONG64 PDE  = (VirtualAddress >> 21) & 0x1FF;
    ULONG64 PDPE = (VirtualAddress >> 30) & 0x1FF;
    ULONG64 PML4 = (VirtualAddress >> 39) & 0x1FF;

    ULONG64 Entry;

    // PML4
    MmCopyMemory(
        &Entry,
        (MM_COPY_ADDRESS){ .PhysicalAddress.QuadPart = (DirectoryTableBase & ~0xFFF) + PML4 * 8 },
        sizeof(ULONG64), MM_COPY_MEMORY_PHYSICAL, &BytesCopied);
    if (!(Entry & 1)) return 0;

    // PDPE
    MmCopyMemory(&Entry,
        (MM_COPY_ADDRESS){ .PhysicalAddress.QuadPart = (Entry & 0xFFFFFFFFFF000) + PDPE * 8 },
        sizeof(ULONG64), MM_COPY_MEMORY_PHYSICAL, &BytesCopied);
    if (!(Entry & 1)) return 0;
    if (Entry & 0x80) return (Entry & 0xFFFFFC0000000) + (VirtualAddress & 0x3FFFFFFF); // 1GB页

    // PDE
    MmCopyMemory(&Entry,
        (MM_COPY_ADDRESS){ .PhysicalAddress.QuadPart = (Entry & 0xFFFFFFFFFF000) + PDE * 8 },
        sizeof(ULONG64), MM_COPY_MEMORY_PHYSICAL, &BytesCopied);
    if (!(Entry & 1)) return 0;
    if (Entry & 0x80) return (Entry & 0xFFFFFFFE00000) + (VirtualAddress & 0x1FFFFF); // 2MB页

    // PTE
    MmCopyMemory(&Entry,
        (MM_COPY_ADDRESS){ .PhysicalAddress.QuadPart = (Entry & 0xFFFFFFFFFF000) + PTE * 8 },
        sizeof(ULONG64), MM_COPY_MEMORY_PHYSICAL, &BytesCopied);
    if (!(Entry & 1)) return 0;

    return (Entry & 0xFFFFFFFFFF000) + PageOffset;
}

NTSTATUS ReadPhysicalMemory(ULONG64 PhysAddr, PVOID Buffer, SIZE_T Size)
{
    MM_COPY_ADDRESS Src;
    Src.PhysicalAddress.QuadPart = PhysAddr;
    SIZE_T Copied;
    return MmCopyMemory(Buffer, Src, Size, MM_COPY_MEMORY_PHYSICAL, &Copied);
}
```

