## mem.hpp — 内存读写封装

```cpp
#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdint>
#include <string>
#include <vector>
#include <iostream>

class Mem {
public:
    HANDLE hProc = nullptr;
    DWORD  pid    = 0;

    // 根据进程名打开目标进程
    bool attach(const std::wstring& procName) {
        pid = findPid(procName);
        if (!pid) { std::wcerr << L"[!] 进程未找到: " << procName << L"\n"; return false; }
        hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
        if (!hProc) { std::wcerr << L"[!] OpenProcess 失败: " << GetLastError() << L"\n"; return false; }
        std::wcout << L"[+] 已附加 PID=" << pid << L"\n";
        return true;
    }

    void detach() { if (hProc) { CloseHandle(hProc); hProc = nullptr; } }

    // 模板读
    template<typename T>
    T read(uintptr_t addr) const {
        T val{};
        SIZE_T n;
        ReadProcessMemory(hProc, (LPCVOID)addr, &val, sizeof(T), &n);
        return val;
    }

    // 模板写
    template<typename T>
    bool write(uintptr_t addr, T val) const {
        SIZE_T n;
        return WriteProcessMemory(hProc, (LPVOID)addr, &val, sizeof(T), &n);
    }

    // 多级指针解引用: base + offsets
    uintptr_t resolvePtr(uintptr_t base, const std::vector<uintptr_t>& offsets) const {
        uintptr_t addr = read<uintptr_t>(base);
        for (size_t i = 0; i < offsets.size() - 1; ++i)
            addr = read<uintptr_t>(addr + offsets[i]);
        return addr + offsets.back();
    }

    // 获取模块基址
    uintptr_t getModuleBase(const std::wstring& modName) const {
        HMODULE mods[1024]; DWORD needed;
        if (!EnumProcessModulesEx(hProc, mods, sizeof(mods), &needed, LIST_MODULES_ALL))
            return 0;
        for (DWORD i = 0; i < needed / sizeof(HMODULE); ++i) {
            wchar_t name[MAX_PATH];
            GetModuleFileNameExW(hProc, mods[i], name, MAX_PATH);
            std::wstring s(name);
            if (s.find(modName) != std::wstring::npos)
                return (uintptr_t)mods[i];
        }
        return 0;
    }

    // AOB 扫描 (单个模块范围)
    uintptr_t aobScan(uintptr_t start, size_t len,
                      const std::vector<int>& pattern) const {
        std::vector<uint8_t> buf(len);
        SIZE_T n;
        ReadProcessMemory(hProc, (LPCVOID)start, buf.data(), len, &n);
        size_t pLen = pattern.size();
        for (size_t i = 0; i + pLen <= n; ++i) {
            bool match = true;
            for (size_t j = 0; j < pLen; ++j) {
                if (pattern[j] != -1 && buf[i+j] != (uint8_t)pattern[j]) {
                    match = false; break;
                }
            }
            if (match) return start + i;
        }
        return 0;
    }

private:
    DWORD findPid(const std::wstring& name) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32W pe{ sizeof(pe) };
        if (Process32FirstW(snap, &pe)) {
            do {
                if (std::wstring(pe.szExeFile) == name) {
                    CloseHandle(snap); return pe.th32ProcessID;
                }
            } while (Process32NextW(snap, &pe));
        }
        CloseHandle(snap); return 0;
    }
};
