// ---- NtQueryInformationProcess (动态获取) ----
typedef NTSTATUS(NTAPI* pfnNtQIP)(HANDLE, ULONG, PVOID, ULONG, PULONG);
typedef NTSTATUS(NTAPI* pfnNtSIT)(ULONG, PVOID, ULONG, PULONG);

// ---- 1. 清除自身 PEB.BeingDebugged ----
// 让外挂进程自身在被检测时不暴露调试状态
inline void clearSelfPEB() {
    PEB* peb = (PEB*)__readgsqword(0x60);          // x64
    peb->BeingDebugged = 0;
    // NtGlobalFlag: 调试时通常为 0x70
    *(DWORD*)((uint8_t*)peb + 0xBC) = 0;           // NtGlobalFlag offset x64
    // ProcessHeap->Flags & ForceFlags
    PVOID heap = peb->ProcessHeap;
    if (heap) {
        *(DWORD*)((uint8_t*)heap + 0x70) = 2;      // Flags
        *(DWORD*)((uint8_t*)heap + 0x74) = 0;      // ForceFlags
