```go
// henc.go — AES-256-GCM + RSA-2048 混合加密/解密工具（自持密钥，完全可逆）
//
// 构建: go build -o henc henc.go
// 用法:
//   henc keygen  [-priv henc_key.pem] [-pub henc_pub.pem]
//   henc encrypt -dir <目标目录> [-pub henc_pub.pem]
//   henc decrypt -dir <目标目录> [-priv henc_key.pem]
//
// 文件格式: magic("HENC1") || RSA-OAEP wrapped AES key(256B) || GCM nonce(12B) || ciphertext||tag
// AAD 绑定原始文件名，密文文件被改名后将无法解密。
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/pem"
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const (
	magic      = "HENC1"
	wrappedLen = 256 // RSA-2048 密文长度
	oaepLabel  = "henc-v1"
	encSuffix  = ".enc"
)

func usage() {
	fmt.Print(`henc — AES-256-GCM + RSA-2048 混合加密工具
用法:
  henc keygen  [-priv henc_key.pem] [-pub henc_pub.pem]
  henc encrypt -dir <目录> [-pub henc_pub.pem]
  henc decrypt -dir <目录> [-priv henc_key.pem]
`)
}

// ---------- 密钥 ----------

func keygen(privPath, pubPath string) error {
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return err
	}
	privPEM := pem.EncodeToMemory(&pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: x509.MarshalPKCS1PrivateKey(key),
	})
	pubDER, err := x509.MarshalPKIXPublicKey(&key.PublicKey)
	if err != nil {
		return err
	}
	pubPEM := pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: pubDER})
	if err := os.WriteFile(privPath, privPEM, 0o600); err != nil {
		return err
	}
	if err := os.WriteFile(pubPath, pubPEM, 0o644); err != nil {
		return err
	}
	fmt.Printf("RSA-2048 keypair:\n  private: %s\n  public:  %s\n", privPath, pubPath)
	return nil
}

func loadPriv(path string) (*rsa.PrivateKey, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	blk, _ := pem.Decode(b)
	if blk == nil {
		return nil, errors.New("pem decode failed")
	}
	if key, err := x509.ParsePKCS1PrivateKey(blk.Bytes); err == nil {
		return key, nil
	}
	k, err := x509.ParsePKCS8PrivateKey(blk.Bytes)
	if err != nil {
		return nil, err
	}
	rk, ok := k.(*rsa.PrivateKey)
	if !ok {
		return nil, errors.New("not an RSA private key")
	}
	return rk, nil
}

func loadPub(path string) (*rsa.PublicKey, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	blk, _ := pem.Decode(b)
	if blk == nil {
		return nil, errors.New("pem decode failed")
	}
	k, err := x509.ParsePKIXPublicKey(blk.Bytes)
	if err != nil {
		return nil, err
	}
	rk, ok := k.(*rsa.PublicKey)
	if !ok {
		return nil, errors.New("not an RSA public key")
	}
	return rk, nil
}

// ---------- 单文件加解密 ----------

func encryptOne(path string, pub *rsa.PublicKey) error {
	plain, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	aesKey := make([]byte, 32) // AES-256
	if _, err := rand.Read(aesKey); err != nil {
		return err
	}
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return err
	}
	ct := gcm.Seal(nil, nonce, plain, []byte(filepath.Base(path)))
	wrapped, err := rsa.EncryptOAEP(rand.Reader, pub, aesKey, []byte(oaepLabel), sha256.New())
	if err != nil {
		return err
	}
	if len(wrapped) != wrappedLen {
		return fmt.Errorf("unexpected wrapped key length: %d", len(wrapped))
	}
	out := make([]byte, 0, len(magic)+wrappedLen+len(nonce)+len(ct))
	out = append(out, magic...)
	out = append(out, wrapped...)
	out = append(out, nonce...)
	out = append(out, ct...)
	if err := os.WriteFile(path+encSuffix, out, 0o600); err != nil {
		return err
	}
	return os.Remove(path)
}

func decryptOne(path string, priv *rsa.PrivateKey) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if len(data) < len(magic)+wrappedLen {
		return errors.New("file too short")
	}
	if string(data[:len(magic)]) != magic {
		return errors.New("bad magic, not an henc file")
	}
	wrapped := data[len(magic) : len(magic)+wrappedLen]
	rest := data[len(magic)+wrappedLen:]

	aesKey, err := rsa.DecryptOAEP(rand.Reader, priv, wrapped, []byte(oaepLabel), sha256.New())
	if err != nil {
		return errors.New("RSA unwrap failed: " + err.Error())
	}
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}
	ns := gcm.NonceSize()
	if len(rest) < ns+gcm.Overhead() {
		return errors.New("truncated ciphertext")
	}
	nonce, ct := rest[:ns], rest[ns:]
	orig := strings.TrimSuffix(filepath.Base(path), encSuffix)
	plain, err := gcm.Open(nil, nonce, ct, []byte(orig))
	if err != nil {
		return errors.New("AES-GCM auth failed (renamed file or wrong key): " + err.Error())
	}
	if err := os.WriteFile(filepath.Join(filepath.Dir(path), orig), plain, 0o644); err != nil {
		return err
	}
	return os.Remove(path)
}

// ---------- 系统目录防护 ----------

func isSystemRoot(p string) bool {
	abs, err := filepath.Abs(p)
	if err != nil {
		return true
	}
	n := strings.ToLower(filepath.ToSlash(abs))
	system := []string{
		"/",
		"/c:/", "/c:/windows", "/c:/program files", "/c:/program files (x86)",
		"/c:/programdata",
		"/etc", "/usr", "/bin", "/sbin", "/boot",
		"/lib", "/lib64", "/proc", "/sys", "/dev", "/root",
	}
	for _, s := range system {
		if n == s || strings.HasPrefix(n, strings.TrimSuffix(s, "/")+"/") {
			return true
		}
	}
	return false
}

// ---------- 目录遍历 ----------

func run(root, pubPath, privPath string, enc bool) error {
	if isSystemRoot(root) {
		return fmt.Errorf("refusing system path: %s", root)
	}
	var pub *rsa.PublicKey
	var priv *rsa.PrivateKey
	var err error
	if enc {
		if pub, err = loadPub(pubPath); err != nil {
			return err
		}
	} else {
		if priv, err = loadPriv(privPath); err != nil {
			return err
		}
	}

	var done, failed int
	walkErr := filepath.WalkDir(root, func(p string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil // 跳过不可读项，继续处理
		}
		isEnc := strings.HasSuffix(p, encSuffix)
		if enc == isEnc {
			return nil // encrypt 只处理非 .enc；decrypt 只处理 .enc
		}
		var e error
		if enc {
			e = encryptOne(p, pub)
		} else {
			e = decryptOne(p, priv)
		}
		if e != nil {
			fmt.Fprintf(os.Stderr, "skip %s: %v\n", p, e)
			failed++
		} else {
			done++
		}
		return nil
	})
	if walkErr != nil {
		return walkErr
	}
	fmt.Printf("processed=%d failed=%d\n", done, failed)
	if failed > 0 {
		return fmt.Errorf("%d file(s) failed", failed)
	}
	return nil
}

// ---------- 入口 ----------

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	var err error
	switch os.Args[1] {
	case "keygen":
		fs := flag.NewFlagSet("keygen", flag.ExitOnError)
		priv := fs.String("priv", "henc_key.pem", "私钥输出路径")
		pub := fs.String("pub", "henc_pub.pem", "公钥输出路径")
		fs.Parse(os.Args[2:])
		err = keygen(*priv, *pub)
	case "encrypt":
		fs := flag.NewFlagSet("encrypt", flag.ExitOnError)
		dir := fs.String("dir", "", "目标目录")
		pubPath := fs.String("pub", "henc_pub.pem", "公钥路径")
		fs.Parse(os.Args[2:])
		if *dir == "" {
			fs.Usage()
			os.Exit(2)
		}
		err = run(*dir, *pubPath, "", true)
	case "decrypt":
		fs := flag.NewFlagSet("decrypt", flag.ExitOnError)
		dir := fs.String("dir", "", "目标目录")
		privPath := fs.String("priv", "henc_key.pem", "私钥路径")
		fs.Parse(os.Args[2:])
		if *dir == "" {
			fs.Usage()
			os.Exit(2)
		}
		err = run(*dir, "", *privPath, false)
	default:
		usage()
		os.Exit(2)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}
