class Http:
    """统一传输层：优先 curl_cffi（真实 TLS/JA3 指纹），否则 aiohttp。"""

    def __init__(self, cfg: Config):
        self.cfg = cfg
        if HAVE_CURL:
            self.s = crequests.AsyncSession(impersonate=cfg.impersonate, timeout=cfg.timeout,
                                            verify=not cfg.insecure)
        else:
            jar = aiohttp.DummyCookieJar()
            self.s = aiohttp.ClientSession(cookie_jar=jar, timeout=aiohttp.ClientTimeout(total=cfg.timeout))

    async def request(self, method: str, url: str, *, headers: dict, proxy: str = "",
                      **kw) -> Resp:
        if HAVE_CURL:
            r = await self.s.request(method, url, headers=headers, proxy=proxy or None,
                                     allow_redirects=False, **kw)
            return Resp(r.status_code, {k: v for k, v in r.headers.items()}, r.text)
        async with self.s.request(method, url, headers=headers, proxy=proxy or None,
                                  allow_redirects=False, **kw) as r:
            return Resp(r.status, dict(r.headers), await r.text())

    async def get(self, url: str, **kw) -> Resp:
        return await self.request("GET", url, **kw)

    async def post(self, url: str, **kw) -> Resp:
        return await self.request("POST", url, **kw)

    async def close(self):
        if HAVE_CURL:
            self.s.close()
        else:
            await self.s.close()


class Signer:
    """签名器。真实算法需从客户端抓包逆向后填入 sign 模板。"""

    def __init__(self, cfg: Config):
        self.cfg = cfg

    def build(self, data: dict, ts: int, nc: str, token: str) -> str:
        c = self.cfg
        jbody = json.dumps(data, separators=(",", ":"), ensure_ascii=False, sort_keys=True)
        if c.sign == "md5_sorted":
            raw = f"{c.app_key}{ts}{nc}{canon_qs(data)}{c.secret}"
        elif c.sign == "md5_mtop":
            raw = f"{token},{ts},{c.app_key},{jbody},{c.secret}"
        elif c.sign == "md5_body":
            raw = f"{jbody}{c.secret}{ts}{nc}"
        elif c.sign == "hmac_sha256":
            raw = f"{c.app_key}\n{ts}\n{nc}\n{jbody}"
            return hmac.new(c.secret.encode(), raw.encode(), hashlib.sha256).hexdigest()
        elif c.sign == "custom":
            raw = c.sign_expr.format(ts=ts, nonce=nc, token=token, data=jbody,
                                     app_key=c.app_key, secret=c.secret)
        else:
            raise ValueError("unknown sign mode: " + c.sign)
        return md5hex(raw)
