    if (!delta) return TRUE;

    IMAGE_DATA_DIRECTORY dir = nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC];
    if (!dir.Size) return TRUE;

    PIMAGE_BASE_RELOC r = (PIMAGE_BASE_RELOC)(base + dir.VirtualAddress);
    while (r->VirtualAddress && r->SizeOfBlock >= sizeof(IMAGE_BASE_RELOC)) {
