import socket, struct, threading, os, sys, shlex

HOST = "0.0.0.0"
PORT = 4444

clients = {}
cid_seq = 0
cur = None
lock = threading.Lock()

def recv_line(c):
    b = b""
    while not b.endswith(b"\n"):
        d = c.recv(1)
        if not d: raise ConnectionResetError("closed")
        b += d
        if len(b) > 65536: break
    return b.decode(errors="ignore").strip()

def recv_exact(c, n):
    d = b""
    while len(d) < n:
        x = c.recv(min(65536, n-len(d)))
        if not x: raise ConnectionResetError("closed")
        d += x
    return d

def recv_frame(c):
    h = recv_exact(c, 8)
    (ln,) = struct.unpack(">Q", h)
    if ln > 200*1024*1024: raise ValueError("frame too large")
    return recv_exact(c, ln) if ln else b""

def send_line(c, s):
    c.sendall((s+"\n").encode())

def send_frame(c, data: bytes):
    c.sendall(struct.pack(">Q", len(data)) + data)

def accept_loop(srv):
    global cid_seq
    while True:
        c, a = srv.accept()
        c.settimeout(60)
