import socket, struct, subprocess, os, sys, time, io

SERVER_HOST = "127.0.0.1"
SERVER_PORT = 4444
RETRY = 5

def recv_line(s):
    b = b""
    while not b.endswith(b"\n"):
        d = s.recv(1)
        if not d: raise ConnectionResetError("closed")
        b += d
    return b.decode(errors="ignore").strip()

def recv_exact(s, n):
    d = b""
    while len(d) < n:
        x = s.recv(min(65536, n-len(d)))
        if not x: raise ConnectionResetError("closed")
        d += x
    return d

def recv_frame(s):
    (ln,) = struct.unpack(">Q", recv_exact(s, 8))
    return recv_exact(s, ln) if ln else b""

def send_frame(s, data: bytes):
    s.sendall(struct.pack(">Q", len(data)) + data)

