```python
#!/usr/bin/env python3
# decrypt.py — PC微信 __APP__.wxapkg 离线解密
# 用法: python decrypt.py -i __APP__.wxapkg -o __APP__.dec.wxapkg [-k key.bin] [--xor-key hex]
# 若无-k则尝试从frida_dump_*.bin/内存dump中自动提取key
import sys, os, argparse, struct

PLAIN_MAGIC = b'V1MMWX'

def load_key(args, data):
    if args.key:
        kb = open(args.key,'rb').read()
        # key.bin可能是dump片段，取16/32字节
        if len(kb) >= 16:
            # 若文件>32字节，尝试定位V1MMWX前16字节
            idx = kb.find(PLAIN_MAGIC)
            if idx >= 16:
                return kb[idx-16:idx]
            return kb[:16] if len(kb)==16 else kb[:32][:16]
        return kb
    if args.xor_key:
        return bytes.fromhex(args.xor_key)
    # 无key: 尝试从data自身header推导? PC包需key, 直接报错提示用frida扫
    return None

def xor_decrypt(body, key):
    out = bytearray(len(body))
    kl = len(key)
    for i,b in enumerate(body):
        out[i] = b ^ key[i % kl] ^ (i & 0xFF)
    return bytes(out)

def aes_cbc_decrypt(body, key):
    try:
        from Crypto.Cipher import AES
    except ImportError:
        print("need pycryptodome: pip install pycryptodome"); sys.exit(1)
    # PC包常见: AES-128-CBC, iv=key, pkcs7, body按16对齐
    iv = key[:16]
    k = (key*2)[:16]
    if len(body)%16!=0:
        body = body[:len(body)//16*16]
    c = AES.new(k, AES.MODE_CBC, iv)
    pt = c.decrypt(body)
    # 去pkcs7
    try:
        pad = pt[-1]
        if 1<=pad<=16 and pt.endswith(bytes([pad])*pad):
            pt = pt[:-pad]
    except: pass
    return pt

def decrypt_file(data, key):
    if data[:6]==PLAIN_MAGIC:
        print("[*] already plain V1MMWX, no decrypt needed")
        return data
    if not (data[0]==0xBE and data[1]==0xED):
        print(f"[!] unknown magic: {data[:14].hex()}, try force xor/aes", file=sys.stderr)
        off=14
    else:
        off=14  # BE ED头固定14字节
        # 新版头: [BE ED][ver 1B][xor?][len...]，body从14开始
    body=data[off:]
    # 1) 先试XOR
    if key and len(key)>=1:
        pt=xor_decrypt(body,key)
        if pt[:6]==PLAIN_MAGIC:
            print(f"[*] XOR success with key {key.hex()}")
            return pt
        # 有些版本XOR后仍有14字节头包裹
        if len(pt)>=14 and pt[14:20]==PLAIN_MAGIC:
            print("[*] XOR success (inner offset 14)")
            return pt[14:] if pt[:6]!=PLAIN_MAGIC else pt
    # 2) 再试AES-CBC
    if key and len(key)>=8:
        try:
            pt=aes_cbc_decrypt(body,key)
            if pt[:6]==PLAIN_MAGIC or b'V1MMWX' in pt[:64]:
                print(f"[*] AES-CBC success with key {key.hex()}")
                # 对齐到V1MMWX
                i=pt.find(PLAIN_MAGIC)
                return pt[i:] if i>0 else pt
            else:
                print(f"[*] AES tried, head={pt[:14].hex()}")
                # 返回XOR结果供人工看
        except Exception as e:
            print(f"AES fail: {e}", file=sys.stderr)
    # 3) 无key兜底: 返回原始
    if key is None:
        print("[!] need key: 用frida dump_key.js扫到的16字节key, 或 -k key.bin", file=sys.stderr)
        sys.exit(2)
    # 默认返回XOR尝试
    return xor_decrypt(body,key)

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("-i","--in",dest="inp",required=True)
    ap.add_argument("-o","--out",dest="out",required=True)
    ap.add_argument("-k","--key",dest="key",default=None,help="16字节key文件")
    ap.add_argument("--xor-key",dest="xor_key",default=None,help="hex串")
    args=ap.parse_args()
    data=open(args.inp,'rb').read()
    print(f"[*] in={len(data)} head={data[:14].hex()}")
    key=load_key(args,data)
    if key: print(f"[*] key={key.hex()} len={len(key)}")
    pt=decrypt_file(data,key)
    open(args.out,'wb').write(pt)
    print(f"[+] wrote {args.out} len={len(pt)} head={pt[:14].hex()}")

if __name__=="__main__": main()
