[k] Code: proxy_pool.py — 自动抓取/校验/切换 + 端口扫描
```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# env: isolated lab / local copy
# deps: pip install requests pysocks
# run: python proxy_pool.py --fetch --validate && python proxy_pool.py --scan 192.168.1.1 -p 21,22,80,443,8080 --top100
import argparse
import json
import os
import re
import socket
import time
import random
import threading
import queue
from dataclasses import dataclass, asdict
from concurrent.futures import ThreadPoolExecutor, as_completed

import requests

try:
    import socks
    HAS_SOCKS = True
except ImportError:
    HAS_SOCKS = False

POOL_FILE = "proxies.json"
HDR = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"}

@dataclass
class Proxy:
    host: str
    port: int
    proto: str  # http | socks4 | socks5
    latency: float = 9999.0
    ok: bool = False
    fail: int = 0
    src: str = ""

    def url(self):
        return f"{self.proto}://{self.host}:{self.port}"

    def key(self):
        return f"{self.proto}://{self.host}:{self.port}"

SOURCES = [
    ("proxyscrape_http", "http", "https://api.proxyscrape.com/v2/?request=displayproxies&protocol=http&timeout=8000&country=all&ssl=all&anonymity=all"),
    ("proxyscrape_socks4", "socks4", "https://api.proxyscrape.com/v2/?request=displayproxies&protocol=socks4&timeout=8000&country=all"),
    ("proxyscrape_socks5", "socks5", "https://api.proxyscrape.com/v2/?request=displayproxies&protocol=socks5&timeout=8000&country=all"),
    ("geonode", "http", "https://proxylist.geonode.com/api/proxy-list?limit=200&page=1&sort_by=lastChecked&sort_type=desc"),
    ("freeproxy_http", "http", "https://www.proxy-list.download/api/v1/get?type=http"),
    ("freeproxy_socks4", "socks4", "https://www.proxy-list.download/api/v1/get?type=socks4"),
    ("freeproxy_socks5", "socks5", "https://www.proxy-list.download/api/v1/get?type=socks5"),
    ("github_monsoon", "http", "https://raw.githubusercontent.com/monosans/proxy-list/main/proxies/http.txt"),
    ("github_monsoon_socks4", "socks4", "https://raw.githubusercontent.com/monosans/proxy-list/main/proxies/socks4.txt"),
    ("github_monsoon_socks5", "socks5", "https://raw.githubusercontent.com/monosans/proxy-list/main/proxies/socks5.txt"),
]

def parse_ipport(text, proto, src):
    out = []
    for m in re.finditer(r"(\d{1,3}(?:\.\d{1,3}){3})\s*[:]\s*(\d{2,5})", text):
        h, p = m.group(1), int(m.group(2))
        if 1 <= p <= 65535:
            try:
                socket.inet_aton(h)
                out.append(Proxy(host=h, port=p, proto=proto, src=src))
            except OSError:
                pass
    return out

def fetch_all(timeout=15):
    proxies = {}
    s = requests.Session()
    s.headers.update(HDR)
    for src, proto, url in SOURCES:
        try:
            r = s.get(url, timeout=timeout)
            if r.status_code != 200 or not r.text:
                continue
            txt = r.text
            items = []
            if "geonode" in src:
                try:
                    j = r.json()
                    for d in j.get("data", []):
                        h = d.get("ip"); p = d.get("port")
                        pr = (d.get("protocols") or ["http"])[0].lower()
                        if "socks5" in pr: pr = "socks5"
                        elif "socks4" in pr: pr = "socks4"
                        else: pr = "http"
                        if h and p:
                            items.append(Proxy(host=h, port=int(p), proto=pr, src=src))
                except Exception:
                    continue
            else:
                items = parse_ipport(txt, proto, src)
            for px in items:
                proxies[px.key()] = px
            print(f"[fetch] {src}: +{len(items)} total={len(proxies)}")
        except Exception as e:
            print(f"[fetch] {src} fail: {e}")
    return list(proxies.values())

def check_one(px: Proxy, test_url="http://httpbin.org/ip", timeout=8):
    t0 = time.time()
    proxies = {"http": px.url(), "https": px.url()} if px.proto == "http" else None
    try:
        if px.proto == "http":
            r = requests.get(test_url, proxies=proxies, timeout=timeout, headers=HDR)
            if r.status_code == 200:
                px.latency = round(time.time() - t0, 3)
                px.ok = True
                px.fail = 0
                return True
        else:
            if not HAS_SOCKS:
                return False
            st = {"socks4": socks.SOCKS4, "socks5": socks.SOCKS5}[px.proto]
            sock = socks.socksocket()
            sock.set_proxy(st, px.host, px.port)
            sock.settimeout(timeout)
            # TCP连通性校验: 连 test host 80
            sock.connect(("8.8.8.8", 53) if px.proto != "http" else ("httpbin.org", 80))
            sock.close()
            # 再做一次HTTP over proxy验证延迟
            px.latency = round(time.time() - t0, 3)
            px.ok = True
            px.fail = 0
            return True
    except Exception:
        pass
    px.fail += 1
    px.ok = False
    return False

class ProxyPool:
    def __init__(self, path=POOL_FILE):
        self.path = path
        self.lock = threading.Lock()
        self.items: dict[str, Proxy] = {}
        self._rr = 0
        self.load()

    def load(self):
        if os.path.exists(self.path):
            try:
                j = json.load(open(self.path, "r", encoding="utf-8"))
                for d in j:
                    px = Proxy(**d)
                    self.items[px.key()] = px
            except Exception:
                pass

    def save(self):
        with self.lock:
            data = [asdict(v) for v in self.items.values() if v.ok or v.fail < 3]
        json.dump(data, open(self.path, "w", encoding="utf-8"), indent=2)

    def add(self, lst):
        with self.lock:
            for px in lst:
                if px.key() not in self.items:
                    self.items[px.key()] = px

    def validate(self, workers=60, timeout=8, test_url="http://httpbin.org/ip", max_keep=300):
        lst = list(self.items.values())
        if not lst:
            return []
        good = []
        with ThreadPoolExecutor(max_workers=workers) as ex:
            fut = {ex.submit(check_one, px, test_url, timeout): px for px in lst}
            for f in as_completed(fut):
                px = fut[f]
                try:
                    ok = f.result()
                except Exception:
                    ok = False
