// We never call MmGetPhysicalAddress on user VA (needs a valid nonpaged PTE lookup that
// faults on user pages). We do our own walk, which keeps us off ObpObReferenceObjectByHandle.
static NTSTATUSWalk_(ULONGLONG target, ULONGLONG dirBase, PHYSICAL_ADDRESS *outPa)
{
    const ULONG  offMask   = 0xFFFULL;
    const ULONG  pdptMask = 0x1FEULL;
    const ULONG  pdMask    = 0x1FEULL;
    const ULONG  ptMask    = 0x1FEULL;
