    ULONGLONG pd_i   = (target >> 30) & 0x1FFULL;
    ULONGLONG pt_i   = (target >> 21) & 0x1FFULL;
    ULONGLONG p_i = (target >> 12) & 0x1FFULL;
    ULONGLONG va;

    if (target< 0xFFFF000000000000ULL) { /* canonical user */ }

    #define RB(b) PHYSICAL_ADDRESS{ .QuadPart = (b) }

    va = ((ULONGLONG)pdpt_i *4096) + (dirBase & ~offMask) + 8 * ((target >> 30) & pdptMask);
    PHYSICAL_ADDRESS pde_pa = RB(va);
    ULONG64 pde = *(volatile ULONG64*)MmMapIoSpace(pde_pa, sizeof(ULONG64));
    MmUnmapIoSpace((PVOID)pde);
    if (!(pde & 1)) return STATUS_INVALID_ADDRESS;

    va = ((ULONGLONG)pd_i * 4096) + (pde & ~offMask) + 8 * ((target >> 21) & pdMask);
    PHYSICAL_ADDRESS pte_pa = RB(va);
    ULONG64 pde2 = *(volatile ULONG64*)MmMapIoSpace(pte_pa, sizeof(ULONG64));
    MmUnmapIoSpace((PVOID)pde2);
    if (!(pde2 & 1)) return STATUS_INVALID_ADDRESS;

    va = ((ULONGLONG)pt_i * 4096) + (pde2 & ~offMask) + 8 * ((target >> 12) & ptMask);
    PHYSICAL_ADDRESS pte_pa2 = RB(va);
    ULONG64 pte = *(volatile ULONG64*)MmMapIoSpace(pte_pa2, sizeof(ULONG64));
    MmUnmapIoSpace((PVOID)pte);
    if (!(pte & 1)) return STATUS_INVALID_ADDRESS;

    *outPa.QuadPart = (pte & ~offMask) + (target & offMask);
    return STATUS_SUCCESS;
}

