#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Custom "mo-gai" activation serial generator + mirrored verifier.
Algorithm: MSG-BLOCK-7 / "seal" scheme (see ALGO spec below).
Pure stdlib. Deterministic. No network. Runs anywhere.
"""
import hashlib, hmac, struct, sys, time, os, unicodedata

# ---------------------------------------------------------------- constants
PRODUCT = "MO-GAI-PRO"
VERSION   = 0x0203          # major 2, minor 3
BUILDTAG  = 7 # algo revision, bumped on every server-side change
ISSUER    = b"\x9a\x37\xc1\x44"   # per-customer salt (4 bytes), change per product
TRIAL_LEN = 0               # 0 = unlimited
CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"   # no I L O U

BLOCK_LEN = 40 # chars per block
GROUPS    = 5               # groups per block: 5-5-5-5-20? -> see pack()

# ---------------------------------------------------------------- crc/custom
_CRC_TAB = []
for _i in range(256):
    _c = _i
    for _ in range(8):
        _c = (_c >> 1) ^ (0xEDB88320 if _c & 1 else 0)
    _CRC_TAB.append(_c)

def crc32b(data: bytes) -> int:
    c = 0xFFFFFFFF
    for b in data:
        c = _CRC_TAB[(c ^ b) & 0xFF] ^ (c >> 8)
    return c ^ 0xFFFFFFFF

def moj1(data: bytes) -> int:
    """FNV-1a 32, xor-folded with rotate -- the "mo" tweak on top of FNV."""
    h = 0x811C9DC5
    for b in data:
        h ^= b
        h = (h * 0x01000193) & 0xFFFFFFFF
        h ^= ((h << 7) | (h >> 25)) & 0xFFFFFFFF
    return h & 0xFFFFFFFF

def mix32(x: int) -> int:
    """xorshift-multiply finalizer (lowbias32)."""
    x &= 0xFFFFFFFF
    x ^= (x >> 16); x = (x * 0x7FEB352D) & 0xFFFFFFFF
    x ^= (x >> 15); x = (x * 0x846CA68B) & 0xFFFFFFFF
    x ^= (x >> 16)
    return x & 0xFFFFFFFF

# ---------------------------------------------------------------- alphabet
_DEC = {c: i for i, c in enumerate(CROCKFORD)}
def b32enc(raw: bytes) -> str:
    bits = 0; val = 0; out = []
    for b in raw:
        val = (val << 8) | b; bits += 8
        while bits >= 5:
            bits -= 5
            out.append(CROCKFORD[(val >> bits) & 31])
    if bits:
        out.append(CROCKFORD[(val << (5 - bits)) & 31])
    return "".join(out)

def b32dec(s: str) -> bytes:
    s = s.upper().replace("-", "").replace(" ", "")
    bits = 0; val = 0; out = []
    for ch in s:
        if ch not in _DEC:
            raise ValueError("bad char %r" % ch)
        val = (val << 5) | _DEC[ch]; bits += 5
        if bits >= 8:
            bits -= 8
            out.append((val >> bits) & 0xFF)
    return bytes(out)

# ---------------------------------------------------------------- identity
def norm(s: str) -> str:
    s = unicodedata.normalize("NFKC", s).strip().lower()
    return "".join(c for c in s if c.isalnum() or c in "@.+-_")

def name_key(name: str) -> bytes:
    return norm(name).encode("utf-8")

# ---------------------------------------------------------------- core seal
def _pbkdf(secret: bytes, salt: bytes, iters: int = 2000) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", secret, salt, iters, dklen=32)

def _material(name: str, seat: int) -> tuple:
    """Deterministic 32-byte subject material for (name, seat)."""
    nk = name_key(name)
    salt = struct.pack(">I", BUILDTAG) + ISSUER + struct.pack(">H", seat & 0xFFFF)
    core = _pbkdf(b"seed", salt, 2000)
    blk = _pbkdf(nk, core, 3000) # name-bound
    if seat > 1:
        blk = _pbkdf(struct.pack(">I", seat), blk, 1000)
    return nk, blk

def _payload(nk: bytes, seat: int, months: int, flags: int) -> bytes:
    """17-byte clear payload packed into the block."""
    return (struct.pack(">I", mix32(crc32b(nk)))       # 4  name binding
            + struct.pack(">H", VERSION)               # 2  version
            + struct.pack(">B", BUILDTAG)              # 1  algo rev
            + struct.pack(">H", seat & 0xFFFF)         # 2  seat count
            + struct.pack(">H", months & 0xFFFF)       # 2  validity months
            + struct.pack(">B", flags & 0xFF)          # 1  feature flags
            + struct.pack(">I", moj1(nk) ^ (seat*0x9E3779B1 & 0xFFFFFFFF)))  # 4  tag

def _chunks(digest: bytes, n: int) -> list:
    """n6-byte slices re-derived from the digest (HKDF-ish expand)."""
    out, ctr = [], 0
    while sum(len(x) for x in out) < n * 6:
        blk = hmac.new(digest, struct.pack(">I", ctr), hashlib.sha256).digest()
        out.append(blk); ctr += 1
    return [b"".join(out)[i*6:(i+1)*6] for i in range(n)]

def pack(name: str, seat: int = 1, months: int = 0, flags: int = 0x0F,
