    sig = _chunks(hmac.new(secret, mat, hashlib.sha256).digest(), 3)  # 18
    body = b32enc(pay + b"".join(sig))                           # 28 chars
    # interleave body with moj1-derived filler -> fixed width, structure hidden
    filler = b32enc(_chunks(_pbkdf(mat, b"filler", 500), 2)[0][:8])     # 13 chars
