#pragma once
#include <windows.h>
#include <stdio.h>

typedef enum {
    PATCH_OK = 0,
    PATCH_NOT_FOUND,
    PATCH_ACCESS_DENIED,
    PATCH_FAILED
} patch_status;

// ---------------------------------------------------------------------------
// 基础: 改内存保护 + 写字节 + 刷新指令缓存
// ---------------------------------------------------------------------------
static int PatchBytes(void* p, const void* bytes, size_t len)
{
    DWORD old = 0;
    if (!VirtualProtect(p, len, PAGE_EXECUTE_READWRITE, &old))
        return PATCH_ACCESS_DENIED;
    memcpy(p, bytes, len);
    FlushInstructionCache(GetCurrentProcess(), p, len);
    VirtualProtect(p, len, old, &old);   // 恢复
    return PATCH_OK;
}

static void* GetExport(HMODULE m, const char* name)
{
    return m ? (void*)GetProcAddress(m, name) : NULL;
}

// 从 PEB->Ldr 里按模块基址反查 HMODULE (比 GetModuleHandle 更可靠, 可处理 unlink)
static HMODULE FindModuleByBase(unsigned char* base)
{
    typedef struct _PEB_LDR_DATA {
        ULONG Length; ULONG Initialized;
        PVOID SsHandle;
        LIST_ENTRY InLoadOrderModuleList;
        LIST_ENTRY InMemoryOrderModuleList;
        LIST_ENTRY InInitializationOrderModuleList;
        PVOID EntryInProgress;
    } PEB_LDR_DATA;

    typedef struct _LDR_DATA_TABLE_ENTRY {
        LIST_ENTRY InLoadOrderLinks;
        LIST_ENTRY InMemoryOrderLinks;
        LIST_ENTRY InInitializationOrderLinks;
        PVOID DllBase;
        PVOID EntryPoint;
        ULONG SizeOfImage;
        PVOID FullDllName;
        PVOID BaseDllName;
        // ...
    } LDR_DATA_TABLE_ENTRY;

    PEB_LDR_DATA* ldr =
        (PEB_LDR_DATA*)__readgsqword(0x30)->Ldr;   // offset 0x18 on x64
    LIST_ENTRY* head = &ldr->InLoadOrderModuleList;
    for (LIST_ENTRY* e = head->Flink; e && e != head; e = e->Flink) {
        LDR_DATA_TABLE_ENTRY* m =
            CONTAINING_RECORD(e, LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if ((unsigned char*)m->DllBase == base) return (HMODULE)base;
    }
    return NULL;
}

static unsigned char* GetModuleBasePC(const wchar_t* name)
{
    return (unsigned char*)GetModuleHandleW(name);
}

