以下是一个基于 Python 和 `pefile` 库的 PE 文件加壳检测脚本。该脚本结合了多种常见的加壳特征检测启发式算法：包括节区香农熵（Entropy）分析、代码段与数据段大小异常比对、特征节区名称检测以及导入表导入函数数量异常分析。

### 环境依赖

运行前请安装 `pefile`：
```bash
pip install pefile
```

### 检测脚本实现

```python
import math
import sys
from typing import Dict, List, Tuple
import pefile

# 常见加壳工具特征节区名称特征
KNOWN_PACKER_SECTIONS = {
    "UPX": [b"UPX0", b"UPX1", b"UPX2", b".UPX0", b".UPX1"],
    "ASPack": [b".aspack", b".adata"],
    "MPRESS": [b".mpress1", b".mpress2"],
    "Themida/WinLicense": [b".themida", b"Themida"],
    "VMProtect": [b".vmp0", b".vmp1", b".vmp2"],
    "PECompact": [b"pec1", b"pec2", b"PECompact2"],
    "Petite": [b".petite"],
    "Enigma": [b".enigma1", b".enigma2"],
}


def calculate_entropy(data: bytes) -> float:
    """计算字节流的香农熵 (Shannon Entropy)，范围 0.0 - 8.0"""
    if not data:
        return 0.0
    entropy = 0.0
    length = len(data)
    occurrences = [0] * 256
    for byte in data:
        occurrences[byte] += 1
    for count in occurrences:
        if count == 0:
            continue
        p = count / length
        entropy -= p * math.log2(p)
    return entropy


def analyze_pe(file_path: str) -> Dict[str, any]:
    """对 PE 文件进行静态启发式加壳分析"""
    results = {
        "is_packed": False,
        "indicators": [],
        "matched_packers": [],
        "sections": [],
    }

    try:
        pe = pefile.PE(file_path, fast_load=False)
    except Exception as e:
        results["indicators"].append(f"解析 PE 文件失败: {e}")
        return results

    # 1. 检查节区名称特征与节区熵
    high_entropy_sections = 0
    size_discrepancy_sections = 0

    for section in pe.sections:
        sec_name = section.Name.rstrip(b"\x00")
        entropy = calculate_entropy(section.get_data())

        vsize = section.Misc_VirtualSize
        rsize = section.SizeOfRawData

        sec_info = {
            "name": sec_name.decode("latin-1", errors="ignore"),
            "entropy": round(entropy, 3),
            "virtual_size": vsize,
            "raw_size": rsize,
        }
        results["sections"].append(sec_info)

        # 匹配已知加壳特征名
        for packer, signatures in KNOWN_PACKER_SECTIONS.items():
            if any(sig in sec_name for sig in signatures):
                if packer not in results["matched_packers"]:
                    results["matched_packers"].append(packer)

        # 检查高熵值：通常 > 7.0 意味着压缩或加密
        if entropy > 7.2:
            high_entropy_sections += 1

        # 检查节区大小差异：加壳程序常有极小的 RawSize 和巨大的 VirtualSize (解压用)
        if vsize > 0 and rsize == 0:
            size_discrepancy_sections += 1
        elif rsize > 0 and (vsize / rsize) > 3.0:
            size_discrepancy_sections += 1

    if results["matched_packers"]:
        results["indicators"].append(
            f"检测到已知壳特征节区: {', '.join(results['matched_packers'])}"
        )

    if high_entropy_sections > 0:
        results["indicators"].append(
            f"存在高熵节区 ({high_entropy_sections} 个)，通常表示存在压缩或加密数据"
        )

    if size_discrepancy_sections > 0:
        results["indicators"].append(
            f"检测到 VirtualSize 显著大于 RawDataSize 的节区 ({size_discrepancy_sections} 个)"
        )

    # 2. 检查入口点 (Entry Point) 是否在非常规节区（例如最后一个节区）
    try:
        entry_point = pe.OPTIONAL_HEADER.AddressOfEntryPoint
        entry_section = None
        for section in pe.sections:
            if (
                section.VirtualAddress
                <= entry_point
                < section.VirtualAddress + section.Misc_VirtualSize
            ):
                entry_section = section
                break

        if entry_section:
            entry_name = entry_section.Name.rstrip(b"\x00").decode(
                "latin-1", errors="ignore"
            )
            # 如果入口点落在最后一个节区，常见于存根代码 (stub)
            if entry_section == pe.sections[-1] and len(pe.sections) > 1:
                results["indicators"].append(
                    f"入口点位于文件的最后一个节区 [{entry_name}]"
                )
    except Exception:
        pass

    # 3. 检查导入表 (Import Table) 数量
    try:
        if hasattr(pe, "DIRECTORY_ENTRY_IMPORT"):
            total_imports = sum(
                len(entry.imports) for entry in pe.DIRECTORY_ENTRY_IMPORT
            )
            total_dlls = len(pe.DIRECTORY_ENTRY_IMPORT)
            if total_imports < 10 and total_dlls <= 2:
                results["indicators"].append(
                    f"导入表极小 (仅引用 {total_dlls} 个 DLL，共 {total_imports} 个函数)，壳通常在运行时动态加载 API"
                )
        else:
            results["indicators"].append("未发现标准导入表 (可能被混淆或破坏)")
    except Exception:
        pass

    # 判定规则：满足多条启发式特征或命中已知特征
    if results["matched_packers"] or len(results["indicators"]) >= 2:
        results["is_packed"] = True

    pe.close()
    return results


def print_report(file_path: str, analysis: Dict[str, any]):
    print("=" * 60)
    print(f"目标文件: {file_path}")
    print(f"判定结果: {'[+] 极可能加壳' if analysis['is_packed'] else '[-] 未检测到明显加壳特征'}")
    print("-" * 60)

    print("启发式特征列表:")
    if analysis["indicators"]:
        for ind in analysis["indicators"]:
            print(f"  * {ind}")
    else:
        print("  * 无显著异常指标")

    print("-" * 60)
    print("节区详细信息 (Sections):")
    print(f"  {'名称':<12} | {'熵 (0-8)':<8} | {'虚拟大小 (VSize)':<15} | {'原始大小 (RSize)':<15}")
    print("  " + "-" * 56)
    for sec in analysis["sections"]:
        print(
            f"  {sec['name']:<12} | {sec['entropy']:<8.3f} | {sec['virtual_size']:<17} | {sec['raw_size']:<15}"
        )
    print("=" * 60)


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(f"用法: python {sys.argv[0]} <PE文件路径>")
        sys.exit(1)

    target_pe = sys.argv[1]
    res = analyze_pe(target_pe)
    print_report(target_pe, res)
```

### 核心检测逻辑解析

1. **香农熵阈值判断**：未加壳的常规 PE 代码段熵值通常在 `5.5 ~ 6.5` 之间，纯数据段更低。经过 UPX、ASPack、VMProtect 等压缩或加密处理后，数据分布接近均匀随机分布，熵值通常显著高于 `7.2`。
2. **虚拟大小与物理大小比对**：加壳工具生成的解密存根节区或目标代码节区，通常具有很小的 `SizeOfRawData`（磁盘占用）和很大的 `Misc_VirtualSize`（内存映射空间），预留给运行时解压展开。
3. **导入表坍缩特征**：很多保护壳只保留 `LoadLibraryA` 和 `GetProcAddress` 两个基本导入函数，其余 API 均在解密后通过哈希或名称动态定位，因此过小的导入表是强指示特征。
